-- ballknowledge BASKETBALL: a separate copy of every table and function, in its own schema called `nba`.
-- Logins are shared (Supabase Auth), everything else (nickname, rating, results, badges, friends, ideas, reports) is separate per sport.
-- Generated by src/62_make_nba_schema.py from schema.sql ... schema_v11.sql. Run once: Supabase -> SQL editor -> paste -> Run. Safe to run again.
-- The last lines of this file also expose the `nba` schema to the API, so nothing else needs clicking.

create schema if not exists nba;
grant usage on schema nba to anon, authenticated, service_role;
alter default privileges in schema nba grant all on tables to anon, authenticated, service_role;
alter default privileges in schema nba grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema nba grant execute on functions to anon, authenticated, service_role;

-- ======== schema.sql ========
-- Beat the Model: accounts, saved progress and global leaderboards.
-- Run once: Supabase dashboard -> SQL editor -> New query -> paste this whole file -> Run.
-- Safe to run again. Sign-up and sign-in use Supabase's own Auth; these tables sit beside it.

-- A nickname for each account that wants to appear on the boards (unique, plain characters only).
create table if not exists nba.profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  nick text not null unique check (nick ~ '^[A-Za-z0-9 _.-]{3,16}$'),
  created_at timestamptz not null default now()
);

-- One row of saved progress per account (plays, XP, achievements, streak days).
create table if not exists nba.progress (
  user_id uuid primary key references auth.users(id) on delete cascade default auth.uid(),
  data jsonb not null,
  updated_at timestamptz not null default now()
);

-- Leaderboard entries. Only the account's own user_id can be written, and only if it has a nickname.
create table if not exists nba.results (
  id bigserial primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  game text not null check (game in ('xp','call','daily','matchday','upset','table','hol','challenge','who','career','club','blur','finish','pvalue','cvalue','number','ttt')),
  league text not null check (league in ('all','E0','D1','SP1','I1','F1')),
  score numeric not null check (score between -300 and 1000),
  week int not null,
  day text not null check (day ~ '^\d{4}-\d{2}-\d{2}$'),
  code text check (code is null or code ~ '^[a-z0-9]{4,10}$')
);
create index if not exists results_board on nba.results (game, league, week);
create index if not exists results_user on nba.results (user_id, created_at);

alter table nba.profiles enable row level security;
alter table nba.progress enable row level security;
alter table nba.results enable row level security;

drop policy if exists "own profile read" on nba.profiles;
create policy "own profile read" on nba.profiles for select to authenticated using (user_id = auth.uid());

drop policy if exists "own progress" on nba.progress;
create policy "own progress" on nba.progress for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

drop policy if exists "own results insert" on nba.results;
create policy "own results insert" on nba.results for insert to authenticated
  with check (user_id = auth.uid() and exists (select 1 from nba.profiles p where p.user_id = auth.uid()));

-- At most 120 entries a minute per account (a simple brake on abuse).
create or replace function nba.results_rate_limit() returns trigger language plpgsql as $$
begin
  if (select count(*) from nba.results where user_id = new.user_id and created_at > now() - interval '1 minute') >= 120 then
    raise exception 'too many scores, slow down';
  end if;
  return new;
end $$;
drop trigger if exists results_rate on nba.results;
create trigger results_rate before insert on nba.results for each row execute function nba.results_rate_limit();

-- Choose or change a nickname. Returns 'ok', 'taken' or 'invalid'.
create or replace function nba.set_nickname(p_nick text) returns text
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null or p_nick !~ '^[A-Za-z0-9 _.-]{3,16}$' then return 'invalid'; end if;
  insert into nba.profiles (user_id, nick) values (auth.uid(), p_nick)
    on conflict (user_id) do update set nick = excluded.nick;
  return 'ok';
exception when unique_violation then return 'taken';
end $$;

-- The public boards. Best streaks take the maximum, everything else adds up. Nobody can read the raw tables.
create or replace function nba.leaderboard(p_game text, p_league text, p_period text, p_week int, p_day text, p_code text)
returns table (nick text, value numeric, plays int)
language sql stable security definer set search_path = nba as $$
  select p.nick,
         case when p_game in ('upset','hol','pvalue','cvalue') then max(r.score) else sum(r.score) end as value,
         count(*)::int as plays
  from nba.results r join nba.profiles p on p.user_id = r.user_id
  where r.game = p_game
    and (p_league = 'all' or r.league = p_league)
    and (p_period = 'all' or (p_period = 'week' and r.week = p_week) or (p_period = 'day' and r.day = p_day))
    and (p_game <> 'challenge' or r.code = p_code)
  group by p.nick
  order by value desc, max(r.created_at) asc
  limit 50;
$$;

grant execute on function nba.leaderboard(text, text, text, int, text, text) to anon, authenticated;
grant execute on function nba.set_nickname(text) to authenticated;
grant select, insert, update on nba.progress to authenticated;
grant insert on nba.results to authenticated;
grant usage, select on sequence nba.results_id_seq to authenticated;
grant select on nba.profiles to authenticated;

-- ======== schema_v2.sql ========
-- ballknowledge, part 2: Elo ratings, ranked matches and open lobbies.
-- Run this in the Supabase SQL editor AFTER schema.sql. Safe to run twice.

create table if not exists nba.ratings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  elo int not null default 1000,
  games int not null default 0,
  wins int not null default 0,
  updated_at timestamptz not null default now()
);
create table if not exists nba.match_reports (
  match_id text not null,
  reporter uuid not null references auth.users (id) on delete cascade,
  opponent uuid not null,
  result text not null check (result in ('win', 'loss', 'draw')),
  created_at timestamptz not null default now(),
  primary key (match_id, reporter)
);
create table if not exists nba.matches_done (match_id text primary key, created_at timestamptz not null default now());
create table if not exists nba.lobbies (
  code text primary key,
  host uuid not null references auth.users (id) on delete cascade,
  game text not null,
  diff text not null,
  seen_at timestamptz not null default now()
);
alter table nba.ratings enable row level security;
alter table nba.match_reports enable row level security;
alter table nba.matches_done enable row level security;
alter table nba.lobbies enable row level security;
-- no policies on purpose: nobody reads or writes these tables directly, only the functions below do.

-- Both players report the same match from their own account. The rating only moves when the two reports agree (one says win, the other loss, or both draw),
-- and only once per match, so nobody can raise their own rating alone. K factor 32, everyone starts on 1000.
create or replace function nba.report_match(p_match text, p_opp uuid, p_result text) returns text
language plpgsql security definer set search_path = nba as $$
declare me uuid := auth.uid(); theirs text; ra int; rb int; ea numeric; sa numeric; k int := 32;
begin
  if me is null then return 'auth'; end if;
  if me = p_opp then return 'self'; end if;
  if p_result not in ('win', 'loss', 'draw') or length(p_match) > 80 then return 'bad'; end if;
  insert into match_reports (match_id, reporter, opponent, result) values (p_match, me, p_opp, p_result) on conflict do nothing;
  if exists (select 1 from matches_done where match_id = p_match) then return 'done'; end if;
  select result into theirs from match_reports where match_id = p_match and reporter = p_opp and opponent = me;
  if theirs is null then return 'waiting'; end if;
  if not ((p_result = 'win' and theirs = 'loss') or (p_result = 'loss' and theirs = 'win') or (p_result = 'draw' and theirs = 'draw')) then return 'conflict'; end if;
  insert into matches_done (match_id) values (p_match) on conflict do nothing;
  if not found then return 'done'; end if;
  insert into ratings (user_id) values (me), (p_opp) on conflict do nothing;
  select elo into ra from ratings where user_id = me;
  select elo into rb from ratings where user_id = p_opp;
  ea := 1 / (1 + power(10, (rb - ra) / 400.0));
  sa := case p_result when 'win' then 1 when 'draw' then 0.5 else 0 end;
  update ratings set elo = greatest(100, round(elo + k * (sa - ea))::int), games = games + 1, wins = wins + (case when p_result = 'win' then 1 else 0 end), updated_at = now() where user_id = me;
  update ratings set elo = greatest(100, round(elo + k * ((1 - sa) - (1 - ea)))::int), games = games + 1, wins = wins + (case when p_result = 'loss' then 1 else 0 end), updated_at = now() where user_id = p_opp;
  return 'applied';
end $$;

create or replace function nba.my_rating() returns table (elo int, games int, wins int)
language sql stable security definer set search_path = nba as $$
  select coalesce(r.elo, 1000), coalesce(r.games, 0), coalesce(r.wins, 0) from (select 1) x left join ratings r on r.user_id = auth.uid();
$$;

create or replace function nba.elo_top() returns table (nick text, elo int, games int, wins int)
language sql stable security definer set search_path = nba as $$
  select p.nick, r.elo, r.games, r.wins from ratings r join profiles p on p.user_id = r.user_id where r.games > 0 order by r.elo desc, r.games desc limit 50;
$$;

create or replace function nba.lobby_ping(p_code text, p_game text, p_diff text) returns void
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null then return; end if;
  if p_code !~ '^[A-Z]{4}$' or length(p_game) > 20 or length(p_diff) > 10 then return; end if;
  delete from lobbies where host = auth.uid() and code <> p_code;
  insert into lobbies (code, host, game, diff, seen_at) values (p_code, auth.uid(), p_game, p_diff, now())
  on conflict (code) do update set seen_at = now(), game = excluded.game, diff = excluded.diff where lobbies.host = auth.uid();
end $$;

create or replace function nba.lobby_close() returns void
language plpgsql security definer set search_path = nba as $$
begin delete from lobbies where host = auth.uid(); end $$;

create or replace function nba.open_lobbies() returns table (code text, nick text, elo int, game text, diff text)
language sql stable security definer set search_path = nba as $$
  select l.code, p.nick, coalesce(r.elo, 1000), l.game, l.diff
  from lobbies l join profiles p on p.user_id = l.host left join ratings r on r.user_id = l.host
  where l.seen_at > now() - interval '45 seconds' order by l.seen_at desc limit 40;
$$;

grant execute on function nba.report_match(text, uuid, text) to authenticated;
grant execute on function nba.my_rating() to authenticated;
grant execute on function nba.lobby_ping(text, text, text) to authenticated;
grant execute on function nba.lobby_close() to authenticated;
grant execute on function nba.open_lobbies() to anon, authenticated;
grant execute on function nba.elo_top() to anon, authenticated;

-- ======== schema_v3.sql ========
-- ballknowledge, part 3: profile pictures and favourites, friends, Elo history.
-- Run in the Supabase SQL editor AFTER schema.sql and schema_v2.sql. Safe to run twice.

alter table nba.profiles add column if not exists avatar text;
alter table nba.profiles add column if not exists fav_player text;
alter table nba.profiles add column if not exists fav_team text;

create table if not exists nba.elo_history (
  id bigserial primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  elo int not null,
  delta int not null,
  at timestamptz not null default now()
);
create index if not exists elo_history_user on nba.elo_history (user_id, at);
create table if not exists nba.friends (
  user_id uuid not null references auth.users (id) on delete cascade,
  friend_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, friend_id)
);
alter table nba.elo_history enable row level security;
alter table nba.friends enable row level security;
-- no policies: everything goes through the functions below.

-- report_match again, now also writing the rating history
create or replace function nba.report_match(p_match text, p_opp uuid, p_result text) returns text
language plpgsql security definer set search_path = nba as $$
declare me uuid := auth.uid(); theirs text; ra int; rb int; na int; nb int; ea numeric; sa numeric; k int := 32;
begin
  if me is null then return 'auth'; end if;
  if me = p_opp then return 'self'; end if;
  if p_result not in ('win', 'loss', 'draw') or length(p_match) > 80 then return 'bad'; end if;
  insert into match_reports (match_id, reporter, opponent, result) values (p_match, me, p_opp, p_result) on conflict do nothing;
  if exists (select 1 from matches_done where match_id = p_match) then return 'done'; end if;
  select result into theirs from match_reports where match_id = p_match and reporter = p_opp and opponent = me;
  if theirs is null then return 'waiting'; end if;
  if not ((p_result = 'win' and theirs = 'loss') or (p_result = 'loss' and theirs = 'win') or (p_result = 'draw' and theirs = 'draw')) then return 'conflict'; end if;
  insert into matches_done (match_id) values (p_match) on conflict do nothing;
  if not found then return 'done'; end if;
  insert into ratings (user_id) values (me), (p_opp) on conflict do nothing;
  select elo into ra from ratings where user_id = me;
  select elo into rb from ratings where user_id = p_opp;
  ea := 1 / (1 + power(10, (rb - ra) / 400.0));
  sa := case p_result when 'win' then 1 when 'draw' then 0.5 else 0 end;
  update ratings set elo = greatest(100, round(elo + k * (sa - ea))::int), games = games + 1, wins = wins + (case when p_result = 'win' then 1 else 0 end), updated_at = now() where user_id = me returning elo into na;
  update ratings set elo = greatest(100, round(elo + k * ((1 - sa) - (1 - ea)))::int), games = games + 1, wins = wins + (case when p_result = 'loss' then 1 else 0 end), updated_at = now() where user_id = p_opp returning elo into nb;
  insert into elo_history (user_id, elo, delta) values (me, na, na - ra), (p_opp, nb, nb - rb);
  return 'applied';
end $$;

create or replace function nba.set_profile(p_avatar text, p_player text, p_team text) returns void
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null then return; end if;
  update profiles set avatar = left(p_avatar, 60), fav_player = left(p_player, 60), fav_team = left(p_team, 60) where user_id = auth.uid();
end $$;

create or replace function nba.my_elo_history() returns table (elo int, delta int, at timestamptz)
language sql stable security definer set search_path = nba as $$
  select h.elo, h.delta, h.at from (select * from elo_history where user_id = auth.uid() order by at desc limit 60) h order by h.at asc;
$$;

create or replace function nba.add_friend(p_nick text) returns text
language plpgsql security definer set search_path = nba as $$
declare fid uuid;
begin
  if auth.uid() is null then return 'auth'; end if;
  select user_id into fid from profiles where lower(nick) = lower(trim(p_nick));
  if fid is null then return 'notfound'; end if;
  if fid = auth.uid() then return 'self'; end if;
  if (select count(*) from friends where user_id = auth.uid()) >= 100 then return 'full'; end if;
  insert into friends (user_id, friend_id) values (auth.uid(), fid) on conflict do nothing;
  if not found then return 'already'; end if;
  return 'ok';
end $$;

create or replace function nba.remove_friend(p_nick text) returns void
language plpgsql security definer set search_path = nba as $$
begin
  delete from friends where user_id = auth.uid() and friend_id = (select user_id from profiles where lower(nick) = lower(trim(p_nick)));
end $$;

create or replace function nba.my_friends() returns table (nick text, elo int, games int, avatar text, fav_player text, fav_team text)
language sql stable security definer set search_path = nba as $$
  select p.nick, coalesce(r.elo, 1000), coalesce(r.games, 0), p.avatar, p.fav_player, p.fav_team
  from friends f join profiles p on p.user_id = f.friend_id left join ratings r on r.user_id = f.friend_id
  where f.user_id = auth.uid() order by coalesce(r.elo, 1000) desc, p.nick;
$$;

-- the public boards and lobbies now also carry the profile picture
drop function if exists nba.elo_top();
create or replace function nba.elo_top() returns table (nick text, elo int, games int, wins int, avatar text)
language sql stable security definer set search_path = nba as $$
  select p.nick, r.elo, r.games, r.wins, p.avatar from ratings r join profiles p on p.user_id = r.user_id where r.games > 0 order by r.elo desc, r.games desc limit 50;
$$;
drop function if exists nba.open_lobbies();
create or replace function nba.open_lobbies() returns table (code text, nick text, elo int, game text, diff text, avatar text)
language sql stable security definer set search_path = nba as $$
  select l.code, p.nick, coalesce(r.elo, 1000), l.game, l.diff, p.avatar
  from lobbies l join profiles p on p.user_id = l.host left join ratings r on r.user_id = l.host
  where l.seen_at > now() - interval '45 seconds' order by l.seen_at desc limit 40;
$$;

grant execute on function nba.report_match(text, uuid, text) to authenticated;
grant execute on function nba.set_profile(text, text, text) to authenticated;
grant execute on function nba.my_elo_history() to authenticated;
grant execute on function nba.add_friend(text) to authenticated;
grant execute on function nba.remove_friend(text) to authenticated;
grant execute on function nba.my_friends() to authenticated;
grant execute on function nba.open_lobbies() to anon, authenticated;
grant execute on function nba.elo_top() to anon, authenticated;

-- ======== schema_v4.sql ========
-- ballknowledge, part 4: live predictions. Run in the Supabase SQL editor AFTER schema.sql, schema_v2.sql and schema_v3.sql. Safe to run twice.
-- Upcoming fixtures and the model's forecast are written by src/40_sync_fixtures.py with the service key (never shipped in the page).
-- Players can only add or change their own pick before kickoff, and the model's forecast stays hidden until you have picked (or the match has kicked off).

create table if not exists nba.fixtures (
  id text primary key,
  league text not null,
  kickoff timestamptz not null,
  home text not null,
  away text not null,
  p_h real, p_d real, p_a real,
  model_pick text check (model_pick in ('H', 'D', 'A')),
  res text check (res in ('H', 'D', 'A')),
  hg int, ag int,
  updated_at timestamptz not null default now()
);
create index if not exists fixtures_kick on nba.fixtures (kickoff);
create table if not exists nba.predictions (
  user_id uuid not null references auth.users (id) on delete cascade,
  fixture_id text not null references nba.fixtures (id) on delete cascade,
  pick text not null check (pick in ('H', 'D', 'A')),
  created_at timestamptz not null default now(),
  primary key (user_id, fixture_id)
);
alter table nba.fixtures enable row level security;
alter table nba.predictions enable row level security;
-- no policies: everything goes through the functions below.

create or replace function nba.open_fixtures(p_league text) returns table (
  id text, league text, kickoff timestamptz, home text, away text, my_pick text, p_h real, p_d real, p_a real, model_pick text,
  res text, hg int, ag int, crowd_h int, crowd_d int, crowd_a int)
language sql stable security definer set search_path = nba as $$
  select f.id, f.league, f.kickoff, f.home, f.away, mp.pick,
         case when mp.pick is not null or f.kickoff <= now() then f.p_h end,
         case when mp.pick is not null or f.kickoff <= now() then f.p_d end,
         case when mp.pick is not null or f.kickoff <= now() then f.p_a end,
         case when mp.pick is not null or f.kickoff <= now() then f.model_pick end,
         f.res, f.hg, f.ag,
         case when mp.pick is not null or f.kickoff <= now() then (select count(*)::int from predictions x where x.fixture_id = f.id and x.pick = 'H') end,
         case when mp.pick is not null or f.kickoff <= now() then (select count(*)::int from predictions x where x.fixture_id = f.id and x.pick = 'D') end,
         case when mp.pick is not null or f.kickoff <= now() then (select count(*)::int from predictions x where x.fixture_id = f.id and x.pick = 'A') end
  from fixtures f left join predictions mp on mp.fixture_id = f.id and mp.user_id = auth.uid()
  where f.kickoff > now() - interval '4 days' and f.kickoff < now() + interval '21 days' and (p_league = 'all' or f.league = p_league)
  order by f.kickoff, f.home;
$$;

create or replace function nba.predict(p_fixture text, p_pick text) returns text
language plpgsql security definer set search_path = nba as $$
declare k timestamptz;
begin
  if auth.uid() is null then return 'auth'; end if;
  if p_pick not in ('H', 'D', 'A') then return 'bad'; end if;
  select kickoff into k from fixtures where id = p_fixture;
  if k is null then return 'notfound'; end if;
  if k <= now() then return 'closed'; end if;
  insert into predictions (user_id, fixture_id, pick) values (auth.uid(), p_fixture, p_pick)
  on conflict (user_id, fixture_id) do update set pick = excluded.pick, created_at = now();
  return 'ok';
end $$;

-- the board: finished fixtures that kicked off in the last p_days days, one point per right result; the model is scored on the same fixtures
create or replace function nba.fixture_board(p_league text, p_days int) returns table (nick text, avatar text, correct int, played int)
language sql stable security definer set search_path = nba as $$
  select p.nick, p.avatar, count(*) filter (where x.pick = f.res)::int, count(*)::int
  from predictions x join fixtures f on f.id = x.fixture_id join profiles p on p.user_id = x.user_id
  where f.res is not null and f.kickoff > now() - make_interval(days => greatest(1, least(p_days, 400))) and (p_league = 'all' or f.league = p_league)
  group by p.nick, p.avatar having count(*) >= 1
  order by 3 desc, 4 asc, 1 limit 50;
$$;
create or replace function nba.model_score(p_league text, p_days int) returns table (correct int, played int)
language sql stable security definer set search_path = nba as $$
  select count(*) filter (where model_pick = res)::int, count(*)::int from fixtures
  where res is not null and kickoff > now() - make_interval(days => greatest(1, least(p_days, 400))) and (p_league = 'all' or league = p_league);
$$;

grant execute on function nba.open_fixtures(text) to anon, authenticated;
grant execute on function nba.predict(text, text) to authenticated;
grant execute on function nba.fixture_board(text, int) to anon, authenticated;
grant execute on function nba.model_score(text, int) to anon, authenticated;

-- ======== schema_v5.sql ========
-- ballknowledge, part 5: match history (opponent and game on every rating change). Run AFTER schema_v3.sql. Safe to run twice.
alter table nba.elo_history add column if not exists opp uuid;
alter table nba.elo_history add column if not exists game text;

drop function if exists nba.report_match(text, uuid, text);
create or replace function nba.report_match(p_match text, p_opp uuid, p_result text, p_game text default null) returns text
language plpgsql security definer set search_path = nba as $$
declare me uuid := auth.uid(); theirs text; ra int; rb int; na int; nb int; ea numeric; sa numeric; k int := 32;
begin
  if me is null then return 'auth'; end if;
  if me = p_opp then return 'self'; end if;
  if p_result not in ('win', 'loss', 'draw') or length(p_match) > 80 then return 'bad'; end if;
  insert into match_reports (match_id, reporter, opponent, result) values (p_match, me, p_opp, p_result) on conflict do nothing;
  if exists (select 1 from matches_done where match_id = p_match) then return 'done'; end if;
  select result into theirs from match_reports where match_id = p_match and reporter = p_opp and opponent = me;
  if theirs is null then return 'waiting'; end if;
  if not ((p_result = 'win' and theirs = 'loss') or (p_result = 'loss' and theirs = 'win') or (p_result = 'draw' and theirs = 'draw')) then return 'conflict'; end if;
  insert into matches_done (match_id) values (p_match) on conflict do nothing;
  if not found then return 'done'; end if;
  insert into ratings (user_id) values (me), (p_opp) on conflict do nothing;
  select elo into ra from ratings where user_id = me;
  select elo into rb from ratings where user_id = p_opp;
  ea := 1 / (1 + power(10, (rb - ra) / 400.0));
  sa := case p_result when 'win' then 1 when 'draw' then 0.5 else 0 end;
  update ratings set elo = greatest(100, round(elo + k * (sa - ea))::int), games = games + 1, wins = wins + (case when p_result = 'win' then 1 else 0 end), updated_at = now() where user_id = me returning elo into na;
  update ratings set elo = greatest(100, round(elo + k * ((1 - sa) - (1 - ea)))::int), games = games + 1, wins = wins + (case when p_result = 'loss' then 1 else 0 end), updated_at = now() where user_id = p_opp returning elo into nb;
  insert into elo_history (user_id, elo, delta, opp, game) values (me, na, na - ra, p_opp, left(p_game, 20)), (p_opp, nb, nb - rb, me, left(p_game, 20));
  return 'applied';
end $$;

drop function if exists nba.my_elo_history();
create or replace function nba.my_elo_history() returns table (elo int, delta int, at timestamptz, opp_nick text, game text)
language sql stable security definer set search_path = nba as $$
  select h.elo, h.delta, h.at, p.nick, h.game
  from (select * from elo_history where user_id = auth.uid() order by at desc limit 60) h left join profiles p on p.user_id = h.opp order by h.at asc;
$$;
grant execute on function nba.report_match(text, uuid, text, text) to authenticated;
grant execute on function nba.my_elo_history() to authenticated;

-- ======== schema_v6.sql ========
-- ballknowledge, part 6: an admin role and the admin dashboard's data. Run AFTER schema.sql and schema_v2.sql. Safe to run twice.
create table if not exists nba.admins (user_id uuid primary key references auth.users (id) on delete cascade);
alter table nba.admins enable row level security;
-- no policies: only the functions below read this table.

-- MAKE YOURSELF ADMIN: run this ONE line separately, with YOUR sign-in email (do not commit your email anywhere):
--   insert into nba.admins select id from auth.users where email = 'YOUR-EMAIL-HERE' on conflict do nothing;

create or replace function nba.is_admin() returns boolean
language sql stable security definer set search_path = nba as $$
  select exists (select 1 from admins where user_id = auth.uid());
$$;

create or replace function nba.admin_stats() returns jsonb
language plpgsql stable security definer set search_path = nba, auth as $$
begin
  if not nba.is_admin() then return null; end if;
  return jsonb_build_object(
    'accounts', (select count(*) from auth.users),
    'new_7d', (select count(*) from auth.users where created_at > now() - interval '7 days'),
    'active_7d', (select count(*) from auth.users where last_sign_in_at > now() - interval '7 days'),
    'active_30d', (select count(*) from auth.users where last_sign_in_at > now() - interval '30 days'),
    'with_nick', (select count(*) from profiles),
    'rated', (select count(*) from ratings where games > 0),
    'ranked_matches', (select count(*) from matches_done),
    'predictions', (select count(*) from predictions),
    'fixtures', (select count(*) from fixtures),
    'last_fixture_sync', (select max(updated_at) from fixtures),
    'open_lobbies', (select count(*) from lobbies where seen_at > now() - interval '45 seconds'),
    'friend_links', (select count(*) from friends),
    'saved_progress', (select count(*) from progress),
    'signups_by_day', (select coalesce(jsonb_agg(jsonb_build_object('d', d, 'n', n) order by d), '[]'::jsonb) from (select created_at::date as d, count(*) as n from auth.users where created_at > now() - interval '14 days' group by 1) x));
end $$;

create or replace function nba.admin_users(p_q text default '') returns table (nick text, email text, created timestamptz, last_seen timestamptz, elo int, games int, wins int)
language sql stable security definer set search_path = nba, auth as $$
  select p.nick, u.email::text, u.created_at, u.last_sign_in_at, coalesce(r.elo, 1000), coalesce(r.games, 0), coalesce(r.wins, 0)
  from auth.users u left join profiles p on p.user_id = u.id left join ratings r on r.user_id = u.id
  where nba.is_admin() and (p_q = '' or lower(coalesce(p.nick, '') || ' ' || coalesce(u.email, '')) like '%' || lower(p_q) || '%')
  order by u.created_at desc limit 300;
$$;
grant execute on function nba.is_admin() to authenticated;
grant execute on function nba.admin_stats() to authenticated;
grant execute on function nba.admin_users(text) to authenticated;

-- ======== schema_v7.sql ========
-- ballknowledge, part 7: "report a problem". Run AFTER schema_v6.sql (it replaces admin_stats to count open reports). Safe to run twice.
create table if not exists nba.reports (
  id bigserial primary key,
  user_id uuid references auth.users (id) on delete set null,
  kind text not null,
  ref text,
  note text,
  status text not null default 'open',
  created_at timestamptz not null default now()
);
alter table nba.reports enable row level security;
-- no policies: reports go in through submit_report and come out only for admins.

create or replace function nba.submit_report(p_kind text, p_ref text, p_note text) returns text
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null then return 'auth'; end if;
  if (select count(*) from reports where user_id = auth.uid() and created_at > now() - interval '1 day') >= 20 then return 'limit'; end if;
  insert into reports (user_id, kind, ref, note) values (auth.uid(), left(p_kind, 20), left(p_ref, 120), left(p_note, 500));
  return 'ok';
end $$;

create or replace function nba.admin_reports(p_status text default 'open') returns table (id bigint, kind text, ref text, note text, status text, created timestamptz, email text)
language sql stable security definer set search_path = nba, auth as $$
  select r.id, r.kind, r.ref, r.note, r.status, r.created_at, u.email::text
  from reports r left join auth.users u on u.id = r.user_id where nba.is_admin() and r.status = p_status order by r.created_at desc limit 200;
$$;

create or replace function nba.admin_resolve_report(p_id bigint) returns void
language plpgsql security definer set search_path = nba as $$
begin if nba.is_admin() then update reports set status = 'resolved' where id = p_id; end if; end $$;

create or replace function nba.admin_stats() returns jsonb
language plpgsql stable security definer set search_path = nba, auth as $$
begin
  if not nba.is_admin() then return null; end if;
  return jsonb_build_object(
    'accounts', (select count(*) from auth.users),
    'new_7d', (select count(*) from auth.users where created_at > now() - interval '7 days'),
    'active_7d', (select count(*) from auth.users where last_sign_in_at > now() - interval '7 days'),
    'active_30d', (select count(*) from auth.users where last_sign_in_at > now() - interval '30 days'),
    'with_nick', (select count(*) from profiles),
    'rated', (select count(*) from ratings where games > 0),
    'ranked_matches', (select count(*) from matches_done),
    'predictions', (select count(*) from predictions),
    'fixtures', (select count(*) from fixtures),
    'last_fixture_sync', (select max(updated_at) from fixtures),
    'open_lobbies', (select count(*) from lobbies where seen_at > now() - interval '45 seconds'),
    'friend_links', (select count(*) from friends),
    'saved_progress', (select count(*) from progress),
    'open_reports', (select count(*) from reports where status = 'open'),
    'signups_by_day', (select coalesce(jsonb_agg(jsonb_build_object('d', d, 'n', n) order by d), '[]'::jsonb) from (select created_at::date as d, count(*) as n from auth.users where created_at > now() - interval '14 days' group by 1) x));
end $$;
grant execute on function nba.submit_report(text, text, text) to authenticated;
grant execute on function nba.admin_reports(text) to authenticated;
grant execute on function nba.admin_resolve_report(bigint) to authenticated;
grant execute on function nba.admin_stats() to authenticated;

-- ======== schema_v8.sql ========
-- ballknowledge, part 8: display names are unique regardless of capital letters ("Tester" and "tester" are the same name). Safe to run twice.
-- If this fails with "could not create unique index", two accounts already share a name apart from capitals: rename one in Table editor, then run again.
create unique index if not exists profiles_nick_lower on nba.profiles (lower(nick));

create or replace function nba.set_nickname(p_nick text) returns text
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null or p_nick !~ '^[A-Za-z0-9 _.-]{3,16}$' then return 'invalid'; end if;
  if exists (select 1 from nba.profiles where lower(nick) = lower(p_nick) and user_id <> auth.uid()) then return 'taken'; end if;
  insert into nba.profiles (user_id, nick) values (auth.uid(), p_nick)
    on conflict (user_id) do update set nick = excluded.nick;
  return 'ok';
exception when unique_violation then return 'taken';
end $$;
grant execute on function nba.set_nickname(text) to authenticated;

-- ======== schema_v9.sql ========
-- ballknowledge, part 9: equipped badges (up to 3, visible to everyone) and owner / admin roles. Run AFTER schema_v3.sql, schema_v4.sql and schema_v6.sql. Safe to run twice.
alter table nba.profiles add column if not exists badges text[] not null default '{}';
alter table nba.admins add column if not exists role text not null default 'admin' check (role in ('owner', 'admin'));

-- the badge ids a player has equipped, minus the staff badges unless that person really holds the role right now
create or replace function nba.clean_badges(p_user uuid, p_badges text[]) returns text[]
language sql stable security definer set search_path = nba as $$
  select coalesce(array(select b from unnest(p_badges) b where b not in ('owner', 'admin')
    or (b = 'owner' and exists (select 1 from admins where user_id = p_user and role = 'owner'))
    or (b = 'admin' and exists (select 1 from admins where user_id = p_user))), '{}');
$$;

create or replace function nba.my_role() returns text
language sql stable security definer set search_path = nba as $$
  select role from admins where user_id = auth.uid();
$$;

create or replace function nba.set_badges(p_ids text[]) returns text
language plpgsql security definer set search_path = nba as $$
declare ids text[];
begin
  if auth.uid() is null then return 'auth'; end if;
  select coalesce(array(select distinct b from unnest(p_ids) b where b ~ '^[a-z0-9_]{2,24}$' limit 3), '{}') into ids;
  if 'owner' = any (ids) and coalesce(nba.my_role(), '') <> 'owner' then ids := array_remove(ids, 'owner'); end if;
  if 'admin' = any (ids) and nba.my_role() is null then ids := array_remove(ids, 'admin'); end if;
  update profiles set badges = ids where user_id = auth.uid();
  return 'ok';
end $$;

-- the public lists now carry each player's equipped badges
drop function if exists nba.elo_top();
create or replace function nba.elo_top() returns table (nick text, elo int, games int, wins int, avatar text, badges text[])
language sql stable security definer set search_path = nba as $$
  select p.nick, r.elo, r.games, r.wins, p.avatar, nba.clean_badges(p.user_id, p.badges) from ratings r join profiles p on p.user_id = r.user_id where r.games > 0 order by r.elo desc, r.games desc limit 50;
$$;
drop function if exists nba.open_lobbies();
create or replace function nba.open_lobbies() returns table (code text, nick text, elo int, game text, diff text, avatar text, badges text[])
language sql stable security definer set search_path = nba as $$
  select l.code, p.nick, coalesce(r.elo, 1000), l.game, l.diff, p.avatar, nba.clean_badges(p.user_id, p.badges)
  from lobbies l join profiles p on p.user_id = l.host left join ratings r on r.user_id = l.host
  where l.seen_at > now() - interval '45 seconds' order by l.seen_at desc limit 40;
$$;
drop function if exists nba.my_friends();
create or replace function nba.my_friends() returns table (nick text, elo int, games int, avatar text, fav_player text, fav_team text, badges text[])
language sql stable security definer set search_path = nba as $$
  select p.nick, coalesce(r.elo, 1000), coalesce(r.games, 0), p.avatar, p.fav_player, p.fav_team, nba.clean_badges(p.user_id, p.badges)
  from friends f join profiles p on p.user_id = f.friend_id left join ratings r on r.user_id = f.friend_id
  where f.user_id = auth.uid() order by coalesce(r.elo, 1000) desc, p.nick;
$$;
drop function if exists nba.fixture_board(text, int);
create or replace function nba.fixture_board(p_league text, p_days int) returns table (nick text, avatar text, correct int, played int, badges text[])
language sql stable security definer set search_path = nba as $$
  select p.nick, p.avatar, count(*) filter (where x.pick = f.res)::int, count(*)::int, nba.clean_badges(p.user_id, p.badges)
  from predictions x join fixtures f on f.id = x.fixture_id join profiles p on p.user_id = x.user_id
  where f.res is not null and f.kickoff > now() - make_interval(days => greatest(1, least(p_days, 400))) and (p_league = 'all' or f.league = p_league)
  group by p.nick, p.avatar, p.user_id, p.badges having count(*) >= 1
  order by 3 desc, 4 asc, 1 limit 50;
$$;
grant execute on function nba.my_role() to authenticated;
grant execute on function nba.set_badges(text[]) to authenticated;
grant execute on function nba.elo_top() to anon, authenticated;
grant execute on function nba.open_lobbies() to anon, authenticated;
grant execute on function nba.my_friends() to authenticated;
grant execute on function nba.fixture_board(text, int) to anon, authenticated;

-- MAKE YOURSELF THE OWNER (run separately, with YOUR sign-in email; do not commit your email anywhere):
--   insert into nba.admins (user_id, role) select id, 'owner' from auth.users where email = 'YOUR-EMAIL-HERE'
--   on conflict (user_id) do update set role = 'owner';

-- ======== schema_v10.sql ========
-- ballknowledge, part 10: roadmap ideas, badge ideas and votes. Run in the Supabase SQL editor AFTER schema_v9.sql. Safe to run twice.
-- Anyone can read the ideas; signed-in players can suggest (5 a day) and vote once per idea; admins set the status.

create table if not exists nba.ideas (
  id bigserial primary key,
  user_id uuid references auth.users (id) on delete set null,
  kind text not null check (kind in ('feature', 'badge', 'game', 'other')),
  title text not null check (char_length(title) between 3 and 80),
  body text check (body is null or char_length(body) <= 300),
  status text not null default 'open' check (status in ('open', 'planned', 'done', 'declined')),
  created_at timestamptz not null default now()
);
create table if not exists nba.idea_votes (
  idea_id bigint not null references nba.ideas (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  primary key (idea_id, user_id)
);
alter table nba.ideas enable row level security;
alter table nba.idea_votes enable row level security;
-- no policies: everything goes through the functions below.

create or replace function nba.submit_idea(p_kind text, p_title text, p_body text) returns text
language plpgsql security definer set search_path = nba as $$
declare nid bigint;
begin
  if auth.uid() is null then return 'auth'; end if;
  if p_kind not in ('feature', 'badge', 'game', 'other') or char_length(coalesce(p_title, '')) not between 3 and 80 then return 'invalid'; end if;
  if (select count(*) from ideas where user_id = auth.uid() and created_at > now() - interval '1 day') >= 5 then return 'limit'; end if;
  insert into ideas (user_id, kind, title, body) values (auth.uid(), p_kind, trim(p_title), nullif(left(trim(coalesce(p_body, '')), 300), '')) returning id into nid;
  insert into idea_votes (idea_id, user_id) values (nid, auth.uid());
  return 'ok';
end $$;

create or replace function nba.list_ideas(p_kind text default null)
returns table (id bigint, kind text, title text, body text, status text, votes int, mine boolean, nick text, created timestamptz)
language sql stable security definer set search_path = nba as $$
  select i.id, i.kind, i.title, i.body, i.status,
         (select count(*)::int from idea_votes v where v.idea_id = i.id),
         exists (select 1 from idea_votes v where v.idea_id = i.id and v.user_id = auth.uid()),
         p.nick, i.created_at
  from ideas i left join profiles p on p.user_id = i.user_id
  where (p_kind is null or i.kind = p_kind) and (i.status <> 'declined' or nba.is_admin())
  order by 6 desc, i.created_at desc limit 100;
$$;

create or replace function nba.vote_idea(p_id bigint) returns text
language plpgsql security definer set search_path = nba as $$
begin
  if auth.uid() is null then return 'auth'; end if;
  if not exists (select 1 from ideas where id = p_id) then return 'missing'; end if;
  if exists (select 1 from idea_votes where idea_id = p_id and user_id = auth.uid()) then
    delete from idea_votes where idea_id = p_id and user_id = auth.uid(); return 'removed';
  end if;
  insert into idea_votes (idea_id, user_id) values (p_id, auth.uid()); return 'added';
end $$;

create or replace function nba.admin_set_idea(p_id bigint, p_status text) returns void
language plpgsql security definer set search_path = nba as $$
begin
  if nba.is_admin() and p_status in ('open', 'planned', 'done', 'declined') then update ideas set status = p_status where id = p_id; end if;
end $$;

grant execute on function nba.list_ideas(text) to anon, authenticated;
grant execute on function nba.submit_idea(text, text, text) to authenticated;
grant execute on function nba.vote_idea(bigint) to authenticated;
grant execute on function nba.admin_set_idea(bigint, text) to authenticated;

-- ======== schema_v11.sql ========
-- ballknowledge, part 11: leaderboards for the newer games (Scramble, Starting XI, Iconic matches, Rapid fire, Bracket buster).
-- Run in the Supabase SQL editor AFTER schema_v10.sql. Safe to run twice. It widens the list of game ids the results table accepts and teaches the leaderboard
-- function that single-run games (Rapid fire, Starting XI, Iconic matches, Bracket buster) show a player's best run while Scramble adds up.

alter table nba.results drop constraint if exists results_game_check;
alter table nba.results add constraint results_game_check check (game in (
  'xp','call','daily','matchday','upset','table','hol','challenge','who','career','club','blur','finish','pvalue','cvalue','number','ttt',
  'scramble','xi','iconic','rapid','bracket'));

create or replace function nba.leaderboard(p_game text, p_league text, p_period text, p_week int, p_day text, p_code text)
returns table (nick text, value numeric, plays int)
language sql stable security definer set search_path = nba as $$
  select p.nick,
         case when p_game in ('upset','hol','pvalue','cvalue','rapid','xi','iconic','bracket') then max(r.score) else sum(r.score) end as value,
         count(*)::int as plays
  from nba.results r join nba.profiles p on p.user_id = r.user_id
  where r.game = p_game
    and (p_league = 'all' or r.league = p_league)
    and (p_period = 'all' or (p_period = 'week' and r.week = p_week) or (p_period = 'day' and r.day = p_day))
    and (p_game <> 'challenge' or r.code = p_code)
  group by p.nick
  order by value desc, max(r.created_at) asc
  limit 50;
$$;
grant execute on function nba.leaderboard(text, text, text, int, text, text) to anon, authenticated;

-- basketball has its own game ids and a single league ("NBA"), so the football lists are replaced by plain patterns
alter table nba.results drop constraint if exists results_game_check;
alter table nba.results add constraint results_game_check check (game ~ '^[a-z0-9_]{2,24}$');
alter table nba.results drop constraint if exists results_league_check;
alter table nba.results add constraint results_league_check check (league ~ '^[A-Za-z0-9]{2,8}$');

-- admins are the same people in both sports
insert into nba.admins (user_id) select user_id from public.admins on conflict do nothing;
grant all on all tables in schema nba to anon, authenticated, service_role;
grant all on all sequences in schema nba to anon, authenticated, service_role;
grant execute on all functions in schema nba to anon, authenticated, service_role;
alter role authenticator set pgrst.db_schemas = 'public, graphql_public, storage, nba';
notify pgrst, 'reload config';
notify pgrst, 'reload schema';
